"""Development-only recurrent CFA sites, scored unchanged on control buffers."""
from datetime import datetime,timezone
import json
from pathlib import Path

import numpy as np

from measure_noise_opening_stages import read_crops
from study_noise_neighbourhoods import ROOT,sha256,git
from study_noise_residual_distributions import pack_cfa


def recurrent_mask(rankings,shape=(64,64),minimum=2):
    if minimum<1 or len(shape)!=2 or min(shape)<1:raise ValueError('Positive recurrence and shape required')
    counts=np.zeros(shape,dtype=np.int32)
    for points in rankings:
        unique={tuple(p) for p in points}
        if any(len(p)!=2 or not (0<=p[0]<shape[0] and 0<=p[1]<shape[1]) for p in unique):raise ValueError('Coordinates outside phase grid')
        for y,x in unique:counts[y,x]+=1
    return counts>=minimum,counts


def score_pair(a,b,mask):
    a,b=np.asarray(a,dtype=float),np.asarray(b,dtype=float);mask=np.asarray(mask,dtype=bool)
    if a.shape!=b.shape or a.shape!=mask.shape or a.ndim!=2 or not np.isfinite(a).all() or not np.isfinite(b).all():raise ValueError('Matching finite phase fields required')
    d=(a-b)/np.sqrt(2.);d-=d.mean();v2=d*d;v4=v2*v2
    if v2.sum()<=0:raise ValueError('Positive variance required')
    top=np.argsort(-v2.ravel(),kind='stable')[:16]
    return dict(selected_count=int(mask.sum()),area_fraction=float(mask.mean()),
        second_moment_share=float(v2[mask].sum()/v2.sum()),fourth_moment_share=float(v4[mask].sum()/v4.sum()),
        selected_in_top16=int(mask.ravel()[top].sum()),selected_centered_residual=d[mask].tolist())


def site_temporal(stack,mask):
    stack=np.asarray(stack,dtype=float)
    if stack.ndim!=3 or stack.shape[0]<2 or stack.shape[1:]!=mask.shape or not np.isfinite(stack).all():raise ValueError('Finite repeated phase fields required')
    centered=stack-stack.mean(axis=(1,2),keepdims=True)
    variance=np.var(centered,axis=0,ddof=1);typical=float(np.median(variance))
    if typical<=0:raise ValueError('Positive typical variance required')
    records=[]
    for y,x in np.argwhere(mask):
        neighbors=[variance[yy,xx] for yy in range(max(0,y-1),min(mask.shape[0],y+2)) for xx in range(max(0,x-1),min(mask.shape[1],x+2)) if (yy!=y or xx!=x) and not mask[yy,xx]]
        local=float(np.median(neighbors)) if neighbors else None
        records.append(dict(y=int(y),x=int(x),centered_temporal_variance=float(variance[y,x]),
            variance_to_phase_median=float(variance[y,x]/typical),neighbor_median_variance=local,
            variance_to_neighbor_median=float(variance[y,x]/local) if local and local>0 else None,
            values=stack[:,y,x].tolist(),centered_values=centered[:,y,x].tolist()))
    return dict(frames=stack.shape[0],phase_median_temporal_variance=typical,sites=records)


def run():
    start=datetime.now(timezone.utc);stamp=start.strftime('%Y%m%dT%H%M%SZ');base=ROOT/'docs/validation/raw'
    names=('repetabilite-distributions-noirs-v001-20261028T114512Z.json','contributions-extremes-bruit-v001-20261028T115125Z.json')
    paths=[base/n for n in names];hashes=[sha256(p) for p in paths]
    repeat,ranks=[json.loads(p.read_text(encoding='utf-8')) for p in paths]
    policy=dict(campaign_id='noise-recurrent-sites-policy-'+stamp,schema_version=1,data_version=1,measured_at_utc=start.isoformat(),
        parents=[dict(path=str(p),sha256=h) for p,h in zip(paths,hashes)],
        policy='For each ISO/ROI/CFA phase select coordinates in pre-RCD top16 centered absolute residual at least twice across original development pairs ONLY. Freeze selected mask before reading control pixels. Score identical coordinates on all retained development/control pairs, including empty masks. Temporal variance from frame-centered phase fields within subset; compare selected sites with whole-phase median and nonselected8 neighbors on phase grid. No choice based on control, no masking/correction, no new threshold calibration. Uses cached20 frames, no unpaired sources, no RAW decode or final reserve access.',
        source=Path(__file__).read_text(encoding='utf-8'),source_sha256=sha256(Path(__file__)))
    policy_path=base/f'politique-sites-recurrents-bruit-v001-{stamp}.json'
    with policy_path.open('x',encoding='utf-8') as h:json.dump(policy,h,ensure_ascii=False,indent=1,allow_nan=False)
    selections=[]
    for iso in (1600,51200):
        for roi in range(3):
            dev=[r for r in ranks['records'] if r['iso']==iso and r['roi']==roi and r['subset']=='development']
            for phase in range(4):
                mask,counts=recurrent_mask([r['stages']['pre_rcd_scaled_cfa'][phase]['top16_yx'] for r in dev])
                selections.append(dict(iso=iso,roi=roi,phase=phase,development_pair_indices=[r['pair_index'] for r in dev],
                    selected=[dict(y=int(y),x=int(x),development_occurrences=int(counts[y,x])) for y,x in np.argwhere(mask)]))
    freeze=base/f'gel-sites-recurrents-bruit-v001-{stamp}.json'
    with freeze.open('x',encoding='utf-8') as h:json.dump(dict(policy=dict(path=str(policy_path),sha256=sha256(policy_path)),selections=selections,frozen_at_utc=datetime.now(timezone.utc).isoformat()),h,ensure_ascii=False,indent=1,allow_nan=False)
    print('FROZEN',freeze,'sites',sum(len(s['selected']) for s in selections),flush=True)
    # No control pixels are consulted before the masks above have been saved.
    cached={}
    for source,item in repeat['native'].items():
        if sha256(Path(item['path']))!=item['sha256'] or sha256(Path(item['pixels']['path']))!=item['pixels']['sha256']:raise ValueError('Cached native changed')
        raw=read_crops(Path(item['pixels']['path']),item['record'])['pre_rcd_scaled_cfa']
        cached[source]=[pack_cfa(v[64:192,64:192]) for v in raw]
    records=[]
    for selection in selections:
        iso,roi,phase=[selection[k] for k in ('iso','roi','phase')];mask=np.zeros((64,64),dtype=bool)
        for p in selection['selected']:mask[p['y'],p['x']]=True
        subsets={}
        for subset in ('development','control'):
            pairs=[r for r in repeat['records'] if r['iso']==iso and r['roi']==roi and r['subset']==subset]
            scores=[];sources=[]
            for pair in pairs:
                values=[cached[p][roi][:,:,phase] for p in pair['paths']]
                scores.append(dict(pair_index=pair['pair_index'],paths=pair['paths'],**score_pair(*values,mask)))
                sources.extend(pair['paths'])
            if len(sources)!=len(set(sources)):raise ValueError('Overlapping pairs in subset')
            temporal=site_temporal(np.stack([cached[p][roi][:,:,phase] for p in sources]),mask)
            subsets[subset]=dict(pairs=scores,temporal=temporal,source_order=sources)
        records.append(dict(**selection,subsets=subsets))
    if len(records)!=24 or hashes!=[sha256(p) for p in paths]:raise ValueError('Coverage/provenance failure')
    now=datetime.now(timezone.utc);out=base/f'sites-recurrents-bruit-v001-{now.strftime("%Y%m%dT%H%M%SZ")}.json'
    result=dict(campaign_id='noise-recurrent-sites-'+stamp,schema_version=1,data_version=1,started_at_utc=start.isoformat(),completed_at_utc=now.isoformat(),measured_at_utc=now.isoformat(),parents=policy['parents'],policy=dict(path=str(policy_path),sha256=sha256(policy_path)),freeze=dict(path=str(freeze),sha256=sha256(freeze)),records=records,
        units='Normalized pre-RCD phase variance; dimensionless moment shares/variance ratios;64x64 phase-grid coordinates.',
        limitations='Pre-RCD samples already clipped and scaled, not latent sensor electrons. Control data previously inspected in earlier studies; prospective mask freeze here does not restore independent blind validation. Temporal variances from4 or6 frames imprecise, no pvalues or universal defect classification. Selection biases development scores high; judge separately on control. Pair differences suppress shared defects. Phase-neighborhood reference is descriptive, not a calibrated matched control. No production change, pixel exclusion, decoder modification, final reserve access or new visual denoise claim.',verdict='development_selected_site_attribution_not_sensor_defect_validation',commit=git('rev-parse','HEAD'))
    with out.open('x',encoding='utf-8') as h:json.dump(result,h,ensure_ascii=False,indent=1,allow_nan=False)
    print('RESULT',out,flush=True)


if __name__=='__main__':run()
